#include <bits/stdc++.h>
using namespace std;

int main() {
    int a[6], sum = 0;
    for (int &x : a) {
        cin >> x;
        sum += x;
    }

    if (sum % 2 != 0) {
        cout << "NO\n";
        return 0;
    }

    int target = sum / 2;
    bool found = false;

    for (int i = 0; i < 6 && !found; ++i)
        for (int j = i + 1; j < 6 && !found; ++j)
            for (int k = j + 1; k < 6; ++k)
                if (a[i] + a[j] + a[k] == target) {
                    found = true;
                    break;
                }

    cout << (found ? "YES\n" : "NO\n");
    return 0;
}

